# patch-sprint3a-jsx.ps1
# Writes 8 TSX files verbatim via base64 to avoid paste-mangling.

$ErrorActionPreference = 'Stop'
cd C:\Users\kevch\Desktop\ProjectFortuna\vendorhub

$files = @{
  'src\app\(authenticated)\account\verify\page.tsx' = ''
  'src\app\(authenticated)\account\verify\VerifyForm.tsx' = ''
  'src\app\(authenticated)\account\offers\page.tsx' = ''
  'src\app\(authenticated)\account\offers\OffersList.tsx' = ''
  'src\app\(admin)\verifications\queue\page.tsx' = ''
  'src\app\listings\[region]\[suburb]\[slug]\OfferButton.tsx' = ''
  'src\app\listings\[region]\[suburb]\[slug]\OfferModal.tsx' = ''
  'src\components\account\VerificationBadge.tsx' = ''
}

foreach ($entry in $files.GetEnumerator()) {
  $path = $entry.Key
  $b64 = $entry.Value
  $content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64))
  $dir = [System.IO.Path]::GetDirectoryName($path)
  if (-not (Test-Path -LiteralPath $dir)) {
    New-Item -ItemType Directory -Force -Path $dir | Out-Null
  }
  Set-Content -LiteralPath $path -Value $content -Encoding UTF8 -NoNewline
  $size = (Get-Item -LiteralPath $path).Length
  Write-Host "Wrote $path ($size bytes)" -ForegroundColor Green
}

Write-Host ''
Write-Host 'All 8 JSX files written. Now clear caches:' -ForegroundColor Cyan
Write-Host '  Remove-Item -Recurse -Force .next -ErrorAction SilentlyContinue'
Write-Host '  npx tsc --noEmit'

